// ---- DOM stubs (define el BEFORE the object literal so closures see it) ----
function makeEl(tag) {
  const el = {};
  el.tag = tag;
  el.children = [];
  el._cls = new Set();
  el.classList = {
    add: c => el._cls.add(c),
    remove: c => el._cls.delete(c),
    toggle: (c, on) => { on ? el._cls.add(c) : el._cls.delete(c); },
    contains: c => el._cls.has(c)
  };
