// helper: run one CHIP-8 "frame" = step instructions until PC returns to the
// main-loop head (0x20A), ticking the delay timer whenever PC sits in the
// wait loop (0x22E..0x232) so the frame limiter can expire.
function runFrame(maxSteps = 2000) {
