      // simulate by directly executing many cycles until DT hits 0.
      // Simplest: step until pc leaves wait loop, but decrement DT via a hack:
      // write 0 into the DT by using the public API? There is none.
      // Instead: just keep stepping; each pass through 0x22E reads DT. We
      // emulate the 60Hz tick by forcing one decrement every 2 steps.
      if (i % 2 === 0) {
        // reach into the closure? Not possible. Use the debugger DT display:
        const dt = parseInt(elements['dbgDT'].textContent, 16);
        if (dt > 0) {
          // emulate timer tick: the script exposes no setter, so we exploit
          // that memory is global — DT is a closure `let`, not reachable.
          // Fallback: break out and let the caller loop more frames.
        }
