rom[patchAt + 2] = 0x60; rom[patchAt + 3] = 0x00;
rom[patchAt + 4] = 0x60; rom[patchAt + 5] = 0x00;
rom[patchAt + 6] = 0x60; rom[patchAt + 7] = 0x00;

