ok(getV(0) === x0, 'demo: key 4 moves left, V0 ' + (x0 + 1) + '->' + getV(0));

// --- key 2 (up): V1 14 -> 13 ---
keys[2] = 1;
for (let i = 0; i < 200 && getPC() !== 0x20A; i++) cycle();
keys[2] = 0;
ok(getV(1) === y0 - 1, 'demo: key 2 moves up, V1 ' + y0 + '->' + getV(1));

// --- key 8 (down): V1 back to 14 ---
keys[8] = 1;
for (let i = 0; i < 200 && getPC() !== 0x20A; i++) cycle();
keys[8] = 0;
