    getContext: null,
    files: [],
  };
  el.classList = {
    add: c => el._cls.add(c),
    remove: c => el._cls.delete(c),
    toggle: (c, on) => { on ? el._cls.add(c) : el._cls.delete(c); },
    contains: c => el._cls.has(c),
  };
  return el;
}

const fillRects = [];
const ctx2d = {
  fillStyle: '',
  fillRect(x, y, w, h) { fillRects.push({ x, y, w, h, style: ctx2d.fillStyle }); },
};

const canvasEl = makeEl('canvas');
canvasEl.getContext = () => ctx2d;

const byId = {};
for (const id of ['screen','keypad','regGrid','status','dbgI','dbgPC','dbgDT','dbgST','dbgRaw','dbgMnem','dbgStack','btnRun','btnPause','btnStep','btnReset','btnDemo','romInput','speed','speedVal']) {
  byId[id] = id === 'screen' ? canvasEl : makeEl();
}

globalThis.document = {
  getElementById: id => byId[id] || makeEl(),
  createElement: t => makeEl(t),
  addEventListener() {},
};
globalThis.window = { addEventListener() {}, AudioContext: undefined, webkitAudioContext: undefined };
globalThis.performance = { now: () => 0 };
globalThis.requestAnimationFrame = () => {};
globalThis.console = console;

// ---- Load emulator ----
new Function(src)();
const E = globalThis.__emu;

// ---- Tests ----
let pass = 0, fail = 0;
const ok = (cond, name, extra='') => {
  if (cond) { pass++; console.log('PASS:', name); }
  else { fail++; console.log('FAIL:', name, extra); }
};

const countPixels = () => E.gfx.reduce((a, b) => a + b, 0);

// 1. reset loads DEMO_ROM at 0x200, fonts at 0x50
E.reset();
ok(E.memory[0x200] === 0x00 && E.memory[0x201] === 0xE0, 'reset: DEMO_ROM loaded at 0x200');
ok(E.memory[0x240] === 0x18 && E.memory[0x244] === 0xFF, 'reset: sprite bytes at 0x240');
ok(E.memory[0x50] === 0xF0, 'reset: font set at 0x50');
ok(E.pc === 0x200, 'reset: pc = 0x200');
ok(E.errorMsg === null, 'reset: no error');

// 2. Run first 5 instructions: CLS, LD V0, LD V1, LD I, DRW -> 20 pixels
for (let i = 0; i < 5; i++) E.cycle();
const px = countPixels();
ok(px === 20, 'demo: ship drawn = 20 pixels', 'got ' + px);
ok(E.V[0] === 0x1C && E.V[1] === 0x0E, 'demo: V0=28 V1=14 (start pos)', `V0=${E.V[0]} V1=${E.V[1]}`);
ok(E.I === 0x240, 'demo: I=0x240');

// 3. Full frame with no keys: erase + redraw, sprite intact
// helper: run one full main-loop frame, ticking DT when in wait loop
function runFrame() {
  let steps = 0;
  const startPc = 0x20A;
  // run until we return to loop start (0x20A) after having left it
  let left = false;
  while (steps++ < 5000) {
    if (E.pc === 0x22E) { // in DT wait loop: tick timer
      if (E.delayTimer > 0) E.delayTimer--;
    }
    E.cycle();
    if (E.errorMsg) throw new Error('emu error: ' + E.errorMsg);
    if (E.pc !== startPc) left = true;
    if (left && E.pc === startPc) return;
  }
  throw new Error('frame did not complete');
}

runFrame();
ok(countPixels() === 20, 'demo: sprite intact after idle frame', 'got ' + countPixels());

// 4. Key 6 (right): x should increase by 1
const x0 = E.V[0];
E.keys[6] = 1;
runFrame();
E.keys[6] = 0;
ok(E.V[0] === (x0 + 1) & 0xFF, 'key 6: ship moves right', `x ${x0} -> ${E.V[0]}`);
ok(countPixels() === 20, 'key 6: sprite still 20 px', 'got ' + countPixels());

// 5. Key 4 (left)
const x1 = E.V[0];
E.keys[4] = 1;
runFrame();
E.keys[4] = 0;
ok(E.V[0] === (x1 - 1) & 0xFF, 'key 4: ship moves left', `x ${x1} -> ${E.V[0]}`);

// 6. Key 8 (down): y + 1
const y0 = E.V[1];
E.keys[8] = 1;
runFrame();
E.keys[8] = 0;
ok(E.V[1] === (y0 + 1) & 0xFF, 'key 8: ship moves down', `y ${y0} -> ${E.V[1]}`);

// 7. Key 2 (up): y - 1
const y1 = E.V[1];
E.keys[2] = 1;
runFrame();
E.keys[2] = 0;
ok(E.V[1] === (y1 - 1) & 0xFF, 'key 2: ship moves up', `y ${y1} -> ${E.V[1]}`);

// 8. render() issues fillRect per pixel (20 ship pixels + 1 bg)
fillRects.length = 0;
E.render();
const shipRects = fillRects.filter(r => r.style === '#39ff6a');
ok(shipRects.length === 20, 'render(): 20 green fillRects for ship', 'got ' + shipRects.length);

// 9. Long-run stability: 50 frames, no error, sprite intact
for (let i = 0; i < 50; i++) runFrame();
ok(E.errorMsg === null && countPixels() === 20, 'stability: 50 frames, no error, sprite intact');

// 10. Disassembler sanity
ok(E.disassemble(0xD015) === 'DRW V0, V1, 5', 'disasm DRW');
ok(E.disassemble(0x00E0) === 'CLS', 'disasm CLS');

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
"}

